def confidentiality(h,level='h3'):
 return '<aside class="case-confidentiality"><span class="eyebrow">'+h['icon']('lock-keyhole')+' CUSTOMER CONFIDENTIALITY</span><'+level+'>Why our case studies are anonymous.</'+level+'><p>We treat customer sourcing relationships as commercially sensitive. Customer identities and all information shared with our factory — including product development, production and packaging — are protected and handled confidentially. We share anonymized project summaries without revealing customer-specific production or packaging details.</p></aside>'

def case_cards(h):
 cards=''.join(f'<a class="project-case-card" href="{c["page"]}"><div class="case-preview-copy"><div class="case-overline"><span class="case-number">PROJECT {i+1:02d}</span><span class="eyebrow">{c["channel"]}</span></div><h3>{c["title"]}</h3><p>{c["challenge"]}</p><div class="case-result"><span>Project outcome</span><p>{c["result"]}</p></div><span class="text-link">Explore the project {h["icon"]()}</span></div></a>' for i,c in enumerate(CASES))
 return '<div class="project-case-grid">'+cards+'</div>'+confidentiality(h)

def delivery_block(h):
 targets='<div class="performance-targets"><article data-performance-target="delivery"><span class="target-label">ON-TIME DELIVERY TARGET</span><strong>98%</strong><p>Target share of orders meeting the agreed delivery milestone. Confirm the completion or dispatch date in the order plan.</p></article><article data-performance-target="defects"><span class="target-label">PRODUCT DEFECT-RATE TARGET</span><strong>&lt;0.5%</strong><p>Target for product defects against the agreed inspection criteria. Measurement scope and acceptance rules are confirmed for the order.</p></article></div>'
 measures='<div class="delivery-measures"><article><strong>40–45</strong><span>calendar days · usual production</span><p>From deposit receipt to production completion. Shipping time is additional; peak-season planning is 40–50 days.</p></article><article><strong>100%</strong><span>manual inspection</span><p>Alongside the agreed lot-sampling plan and the customer’s inspection requirements.</p></article><article>'+count_up(600000)+'<span>pieces/month · normal output</span><p>Combined kitchenware, food-storage and cookware output; confirm capacity for the selected product mix.</p></article><article><strong>3 stages</strong><span>order progress updates</span><p>At scheduling, as completion approaches and after inspection. Timing effects from changes are communicated in advance.</p></article></div>'
 return '<section class="section delivery-planning" id="delivery"><div class="wrap">'+h['heading']('Delivery & quality','Clear targets.<br>Defined working arrangements.','Plan against the agreed product, inspection and delivery milestones. The percentage figures below are targets, not audited historical results.')+targets+'<h3 class="delivery-working-heading">How we plan and check your order</h3>'+measures+'<div class="delivery-footnote"><p>Agree on the promised milestone, inspection plan and shipping terms for your order.</p>'+h['link']('contact.html?interest=delivery-review','Discuss your delivery plan')+'</div></div></section>'
def guide_cta(h,title,href,text):
 return '<aside class="guide-context-link"><div><span class="eyebrow">Buying guide</span><h3>'+title+'</h3><p>'+text+'</p></div>'+h['link'](href,'Read the guide')+'</aside>'
def revise_reference(filename,title,description,body,h):
 link,image,icon,heading,intro,cta=h['link'],h['image'],h['icon'],h['heading'],h['intro'],h['cta']
 if filename=='index.html':
  body=body.replace('Stainless food storage.<br><em>Made for your brand.</em>','Stainless steel kitchenware.<br><em>OEM manufacturing in Chaozhou.</em>')
  old='304, 316L or titanium. Practical sizes, thoughtful lids and brand-ready details — made by a kitchenware manufacturing team with roots since 1985. Build a food-storage range with product design and production under one roof.'
  new='Food storage containers, cookware, kettles and serving ware — developed and manufactured in <strong>Caitang, Chaozhou, Guangdong, China</strong>. Our priority is <strong>food storage and cookware</strong>, with <strong>OEM development from your drawing or sample</strong> and coordinated sourcing for additional stainless steel kitchenware.'
  body=body.replace('<section class="section factory-proof"',factory_film(h)+'<section class="section factory-proof"',1)
  if old not in body:raise RuntimeError('Expected previous homepage lead')
  body=body.replace(old,new).replace('Find your product fit','Explore kitchenware & OEM',1)
  body,count=re.subn(r'<a class="hero-product".*?</a>','',body,count=1,flags=re.S)
  if count!=1:raise RuntimeError('Expected the previous factory mini-card')
  ribbon='<div class="wrap factory-ribbon"><a class="factory-ribbon-photo" href="manufacturing.html">'+image('assets/factory-source/factory-forming.jpg','MayLendy forming workshop in Caitang, Chaozhou')+'</a><div><span class="eyebrow">THE FACTORY BEHIND YOUR RANGE</span><h2>Materials in. Products out.<br>One manufacturing conversation.</h2><p>See the material, forming, tooling and inspection stages behind your product.</p><div class="factory-film-links">'+link('#factory-film','Watch workshop video')+link('manufacturing.html','Explore our factory')+'</div></div></div>'
  body=body.replace('<div class="wrap hero-bottom">',ribbon+'<div class="wrap hero-bottom">',1)
  body=body.replace('<section class="section evidence-summary">','<section class="section project-cases-home"><div class="wrap">'+heading('Project experience','Product challenges.<br>Practical responses.','From seal performance to nesting design, explore how we work through a customer’s product requirements.',link('oem.html#projects','OEM project experience'))+case_cards(h)+'</div></section>'+delivery_block(h)+'<section class="section evidence-summary">',1)
  title='Stainless Steel Kitchenware Manufacturer & OEM Factory'
  description='MayLendy manufactures stainless steel food storage containers, cookware, kettles and serving ware in Chaozhou, Guangdong, China, with OEM development and coordinated kitchenware sourcing.'
