 if filename=='food-storage.html':
  description='Explore MayLendy stainless steel food storage containers with PP, silicone glass, silicone, detachable-clip PP, MS, stainless steel and bamboo lid options. Compare materials and specifications.'
  section='<section class="section"><div class="wrap">'+guide_cta(h,'Choosing the Right Food Storage Lid','guide-storage-lids.html','Compare the closure, material and care conditions for the matching model.')+'</div></section>'
