  body=body.replace('<section class="section surface-soft"><div class="wrap">','<section class="section surface-soft" id="steel-lids"><div class="wrap">',1)
  body=body.replace('<article class="model-card" id="bamboo-options">','<span id="bamboo-lids" class="anchor-target"></span><article class="model-card" id="bamboo-options">')
