  flow=[('Brief','Share the product, market, quantity and timing you need.'),('Review','Agree the material, construction, drawings and development scope.'),('Sample','Review prototypes or catalog samples for appearance, fit and handling.'),('Refine & approve','Work through feedback, testing and any mold or product adjustments.'),('Manufacture & inspect','Schedule after the agreed deposit and check the order against the approved requirements.'),('Pack & dispatch','Confirm packaging, complete inspection and arrange shipment under the agreed terms.')]
  body+='<section class="section"><div class="wrap">'+heading('From brief to shipment','Six practical project stages.','Keep decisions visible before moving to the next stage.')+'<ol class="oem-flow">'+''.join(f'<li><span>{i+1:02d}</span><h3>{a}</h3><p>{b}</p></li>' for i,(a,b) in enumerate(flow))+'</ol></div></section>'
  body+=tail+'<section class="section" id="projects"><div class="wrap">'+heading('Project experience','Two challenges.<br>Two manufacturing responses.','Anonymized examples supplied by MayLendy. Results refer to the specific projects described.')+case_cards(h)+'</div></section>'+delivery_block(h)+cta('Bring your drawing, sample or product target.','Share the model, construction, quantities and market. We will work through the OEM route, sample requirements and production conditions with you.')
  title='Stainless Steel Kitchenware OEM — Drawings, Samples & Custom Development'
  description='Develop custom stainless steel kitchenware with MayLendy in Chaozhou. Review drawings, materials, tooling, sample approval and production, with two anonymized project examples.'
