def build_cases(h):
 for c in CASES:
  body=h['intro']('OEM project / '+c['channel'],c['title']+'.',c['summary'],h['link']('oem.html#projects','Back to OEM projects'))
  body+='<section class="section"><div class="wrap case-detail-layout"><div class="case-project-context"><span class="eyebrow">PROJECT AT A GLANCE</span><dl class="spec-list"><div><dt>Customer channel</dt><dd>'+c['channel']+'</dd></div><div><dt>Product</dt><dd>'+c['product']+'</dd></div></dl>'+confidentiality(h,'h2')+'</div><div>'+''.join('<article class="case-stage"><span class="eyebrow">'+a+'</span><h2>'+b+'</h2><p>'+c[key]+'</p></article>' for a,b,key in [('01 / THE CHALLENGE','What the project needed','challenge'),('02 / OUR APPROACH','How the team responded','approach'),('03 / THE RESULT','The project outcome','result')])+h['link'](c['link'],'Explore the product family')+'</div></div></section>'
  body+='<section class="section surface-soft"><div class="wrap"><p class="section-note">'+('The leak-test outcome applies to the product made with this project’s completed mold. Seal requirements are reviewed for each model and lid configuration.' if c['id']=='leakage' else 'The larger tray and two smaller containers form a coordinated set for packing and shipping. Nesting fit is reviewed with the chosen sizes and lids.')+'</p></div></section>'+h['cta']('Have a similar product challenge?','Bring the reference sample or drawing, the performance requirement and your intended market. We can discuss the development work your project needs.')
  h['page'](c['page'],c['title'],c['summary'],body,'oem.html')
 (ROOT/'data/oem-cases.json').write_text(json.dumps(CASES,ensure_ascii=False,indent=2),encoding='utf-8')
